SELECT (SELECT * FROM pragma_auto_vacuum) AS auto_vacuum, (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name IN ('t1','t2')) AS table_count, (SELECT count(*) FROM pragma_table_info('t1')) AS t1_column_count, (SELECT count(*) FROM pragma_table_info('t2')) AS t2_column_count, (SELECT sum(cid) FROM pragma_table_info('t1')) AS t1_cid_sum, (SELECT sum(cid) FROM pragma_table_info('t2')) AS t2_cid_sum, (SELECT name FROM pragma_table_info('t1') WHERE cid=0) AS t1_first_column, (SELECT name FROM pragma_table_info('t1') WHERE cid=149) AS t1_last_column, (SELECT name FROM pragma_table_info('t2') WHERE cid=0) AS t2_first_column, (SELECT name FROM pragma_table_info('t2') WHERE cid=149) AS t2_last_column, (SELECT count(*) FROM t1) AS t1_rows, (SELECT count(*) FROM t2) AS t2_rows;